from dsl import *
J,R,S,A="events_jianghu","events_random","events_story","events_action"
def H(f,k,label,text,need,req=None,**eff):
    r={"manor":need}; r.update(req or {})
    hook(f,k,C(label,O(text,**eff),req=r,hidden=True))
# 객사
H(J,"피난민행렬","행렬의 앞머리를 장원 쪽 고갯길로 돌린다","맨 앞 노인에게 문패의 탁본을 쥐여 주고 고갯길을 일렀다. 북소리는 큰길을 따라갔다. 행렬의 꼬리가 고개를 넘을 때까지 후미에 서 있었다. 청지기는 솥을 몇 개 더 걸어야 할 것이다.","객사",alignment=AL(j=70),fame=25,stats={"mind":4},flags=["장원_식구","장원_마을"])
H(J,"도망병","장원의 문지기로 보낸다. 달아난 값은 문 앞에서 치르라 한다","군관에게는 엉뚱한 골짜기를 가리켰다. 젊은이는 문패의 탁본을 받아 들고 몇 번이나 절을 했다. \"다시는 등을 보이지 않겠습니다.\" 문지기가 등을 보이면 집이 뚫린다. 그도 그것을 안다.","객사",alignment=AL(m=40),stats={"mind":3},flags=["장원_식구"])
H(J,"길잃은아이","아이를 장원 객사에 맡겨 두고 사내들의 뒤를 밟는다","사내들은 아이의 숙부가 보낸 자들이었다. 재산을 두고 조카를 치우려던 것이다. 관아에 넘기고 아이의 어미를 찾아 주었다. 아이는 장원을 떠나며 청지기의 수염을 한 번 더 잡아당겼다.","객사",alignment=AL(j=60),fame=15,stats={"mind":4})
H(J,"고리대의딸","빚 문서를 장원의 이름으로 사들이고 부녀를 객사의 일꾼으로 들인다","고리대금업자는 장원의 이름을 듣고 값을 깎아 불렀다. 문서는 장원 궤에 들어갔다. 부녀는 삯에서 조금씩 갚기로 했다. 이자는 붙이지 않았다. 청지기가 그것을 못마땅해했다.","객사",alignment=AL(s=50),silver=-40,stats={"mind":3},flags=["장원_식구"])
H(J,"탈교자","장원 객사에 숨기고 끌려간 길을 그리게 한다","피리 소리는 엉뚱한 숲으로 흘러갔다. 여인은 객사 골방에서 사흘 밤낮 길을 그렸다. 수백 명이 끌려간 길이다. 그림을 무림맹의 전서구에 실어 보냈다. 여인은 장원 부엌에 남았다.","객사",alignment=AL(j=70),fame=20,stats={"mind":4,"martial":2},flags=["장원_식구"])
H(J,"눈길의호송","포졸들을 장원 객사에 재우고 밤사이 죄수의 말을 듣는다","포졸들은 더운 방과 술에 곯아떨어졌다. 죄수는 세곡 창고의 열쇠를 쥐었던 서리였다. 빈 창고의 죄를 혼자 뒤집어썼다고 한다. 진짜 장부가 묻힌 곳을 받아 적었다. 그 장부는 쓸모가 많을 것이다.","객사",alignment=AL(s=60),silver=70,stats={"mind":3})
H(J,"마도_문닫는마을","문이 닫히지 않는 내 집으로 발길을 돌린다","마을을 비켜 산자락으로 올랐다. 청지기는 내 얼굴을 보고도 대문을 닫지 않았다. \"주인의 집입니다.\" 그 한마디에 밥이 넘어갔다. 식객들은 그날 밤 마당에 나오지 않았다.","객사",alignment=AL(m=40),stats={"mind":5},hp_pct=15)
H(J,"늙은무희","장원 객사의 볕 드는 방을 내주겠다고 한다","무희는 부채로 입을 가리고 한참 웃었다. \"이 나이에 거둬 가겠다는 사내가 다 있네.\" 이튿날 보따리 하나를 들고 산자락을 올랐다. 객사 마루에서 부채가 펴질 때마다 식객들이 숨을 죽인다.","객사",stats={"martial":4,"mind":2},flags=["장원_식객"])
H(J,"맹인악사","장원의 식객으로 들인다. 밤마다 담 밖으로 곡이 흐르게 한다","악사는 값을 묻지 않았다. 담 안에서 타는 비파 소리에 담 밖의 술잔이 떨린다는 소문이 돌았다. 그 뒤로 밤에 장원 담을 넘보는 자가 없다.","객사",alignment=AL(m=50),stats={"internal":4},flags=["장원_식객"])
# 연무장
H(J,"무관문패","문하생들에게 장원 연무장의 길을 일러 준다","수련비를 돌려받지 못한 문하생 여럿이 이튿날 산자락을 올랐다. 관장은 문패를 내리지 않았지만 마당이 비었다. 장원 궤에 수련비가 새로 쌓인다. 청지기가 오랜만에 웃었다.","연무장",alignment=AL(s=50),silver=60,flags=["장원_제자"])
H(J,"칼가는아이","장원 연무장의 병기 시중으로 들인다","아이는 숫돌 지게를 진 채 산자락을 올랐다. 연무장의 병기가 날마다 빛난다. 아이 손의 상처는 아물었고, 요즘은 날을 가는 틈틈이 식객들의 발놀림을 흉내 낸다.","연무장",alignment=AL(j=50),stats={"mind":3},flags=["장원_식구","장원_제자"])
H(A,"수련_아이들","장원 연무장으로 오라고 일러 준다. 막대기 대신 목봉을 쥐여 주겠다고","아이들이 담장에서 우르르 내려왔다. 부모들이 뒤쫓아 왔다가 연무장을 보고는 떡을 쪄 왔다. 사범 노릇을 할 식객이 투덜거리며 줄을 세웠다.","연무장",fame=10,art_mastery={"경공":5},flags=["장원_제자"])
H(J,"천민의검무","묻지 않는 조건으로 장원의 사범 자리를 내준다","광대는 한참 내 얼굴을 보았다. \"묻지 않는다는 말을 믿어 본 적이 없소.\" 그래도 왔다. 연무장에서 그는 보법을 가르치지 않는다. 다만 그에게 배운 아이들은 넘어지지 않는다.","연무장",alignment=AL(s=40),stats={"martial":5},flags=["장원_사범"])
H(J,"사형제싸움","둘을 장원 연무장에 세우고 식객들 앞에서 끝을 보게 한다","식객들이 둘러앉아 판돈을 걸었다. 둘은 사흘을 겨루고 나란히 쓰러졌다. 유품은 연무장 시렁에 올라갔다. 이긴 쪽이 가져가기로 했는데 둘 다 아직 일어나 겨루는 중이다.","연무장",alignment=AL(m=50),silver=50,stats={"martial":4},flags=["장원_제자"])
H(J,"일인전승","장원 연무장 한쪽에 그 문파의 자리를 내준다","늙은이는 지팡이를 짚고 산자락을 올랐다. 연무장 구석에 삼백 년 된 문파의 명패가 걸렸다. 아이 하나가 그 앞에서 초식을 따라 한다. 늙은이는 그것을 제자라 부르지 않는다. 그래도 날마다 나와 본다.","연무장",alignment=AL(j=60),fame=15,stats={"martial":5},flags=["장원_사범"])
H(J,"눈먼고수","한 수를 받고, 장원 연무장의 아이들 소리도 들어 달라 청한다","노인은 한 수 끝에 지팡이를 거두었다. \"소리가 많은 집이군. 가 보지.\" 연무장 마루에 앉은 노인은 발소리만 듣고 아이들의 자세를 고친다. 틀린 발소리가 날마다 줄어든다.",{"연무장":2},stats={"martial":6,"mind":2},flags=["장원_사범"])
H(J,"파계승","장원에 숨기고 연무장의 사범으로 삼는다","추격승들은 산자락 아래에서 발길을 돌렸다. 닫힌 대문을 두드리는 것은 소림의 법이 아니다. 사내는 연무장에서 나한권을 가르친다. 고기와 술은 담 밖에서 먹으라 했더니 담을 넘는 솜씨만 늘었다.","연무장",req={"not_sect":["소림"]},alignment=AL(m=40),stats={"external":5},flags=["장원_사범"])
H(J,"유배장수","병서를 들고 장원으로 오시라 청한다. 식객들에게 진을 가르쳐 달라고","장수는 군막을 걷으며 코웃음을 쳤다. \"강호 놈들에게 진이라.\" 달포 뒤 장원의 식객들은 열을 맞춰 걷는다. 담 밖에서 보면 무슨 군영 같다고 고을 사람들이 수군댄다.","연무장",alignment=AL(m=40),stats={"external":4,"mind":3},flags=["장원_사범","장원_식객"])
# 약방
H(J,"독우물","두레박의 물을 장원 약방에 보내 무슨 독인지부터 가린다","약방에서 답이 왔다. 귀신이 아니라 상류의 염색집이 버린 잿물이다. 해독할 약 첩과 함께 물길을 돌릴 자리를 그린 종이가 왔다. 마을 사람들은 염색집 주인을 우물가에 세워 놓고 그 물을 떠 주었다.","약방",alignment=AL(j=60),fame=15,stats={"mind":5})
H(J,"왕진요청","장원 약방의 탕약으로 깨우고, 대감 집안을 장원의 뒷배로 묶는다","탕약 세 첩에 대감 아들이 눈을 떴다. 대감은 은자를 내밀었지만 받지 않았다. 대신 문서 한 장을 받았다. 이 고을 관아는 앞으로 산자락의 장원을 건드리지 않는다.","약방",alignment=AL(m=50),stats={"mind":4},fame=10,flags=["장원_마을"])
H(J,"역병의고을","장원 약방의 약 수레를 성문 앞에 대고 문을 열라 한다","수레가 닿자 성벽 위가 조용해졌다. 성문이 열리고 약 첩이 손에서 손으로 넘어갔다. 약방 사람들은 열흘을 성 안에서 지냈다. 고을은 그 뒤로 해마다 햇곡을 장원에 올려 보낸다.",{"약방":2},alignment=AL(j=80),fame=35,stats={"mind":5},flags=["장원_마을"])
H(J,"눈먼약장수","쉬는 법은 됐고, 장원 약방에 앉아 달라 청한다","약장수는 내 손목을 놓지 않고 웃었다. \"쉴 줄 모르는 사람이 쉴 집은 지어 놓았구려.\" 약방 마루에 앉은 그는 문턱을 넘는 발소리만으로 병을 반쯤 맞힌다.","약방",stats={"internal":4},flags=["장원_의원"])
H(J,"약초꾼의부탁","꽃을 뿌리째 떠서 장원 약초밭에 옮겨 심고 해마다 반을 보내기로 한다","절벽의 꽃은 한 포기였지만 밭에서는 이듬해 열 포기가 되었다. 노인은 해마다 제 몫을 받으러 산자락을 오른다. 올 때마다 밭고랑을 고쳐 놓고 간다.","약방",alignment=AL(s=40),silver=30,stats={"internal":3})
H(J,"은거명의의제자","밭을 장원 약방 아래 둔다. 세금과 산적은 장원이 맡는다","관아 사람은 장원의 이름이 적힌 문서를 보고 돌아갔다. 산적은 식객 둘이 다녀온 뒤로 오지 않는다. 소녀는 거둔 약초의 셋에 하나를 장원으로 보낸다. 스승의 처방전도 한 장씩 베껴 보낸다.","약방",alignment=AL(s=50),stats={"mind":3},flags=["장원_의원"])
H(A,"요양_떠돌이의원","침값 대신 장원 약방의 약재를 내주겠다고 한다","의원은 약재 이름을 듣더니 침통을 다시 열었다. \"그런 약재를 쌓아 둔 집이 있소?\" 침은 깊고 고르게 들어갔다. 의원은 그길로 장원 쪽 길을 물었다.","약방",alignment=AL(s=30),hp_pct=30,art_mastery={"심공":5},flags=["장원_의원"])
# 서고
H(J,"유언쓰는서생","돌아오지 못한 자의 글은 장원 서고에서 맡겠다고 한다","서생이 붓을 멈추고 나를 보았다. 줄 선 무인들도 농담을 멈추었다. 유언마다 받을 사람의 이름을 적어 궤에 넣었다. 돌아온 자는 제 손으로 찾아가면 되고, 그렇지 못한 자의 글은 장원이 전한다.","서고",alignment=AL(j=70),fame=25,stats={"mind":5},flags=["장원_장서"])
H(J,"훈장의회초리","회초리를 꺾고, 아이들을 장원 서고의 글방으로 옮긴다","훈장은 꺾인 회초리를 들고 관아로 뛰었지만 아이들의 팔을 본 아전이 그를 돌려보냈다. 서고 아랫방에 작은 책상이 줄지어 놓였다. 글 읽는 소리가 연무장의 기합 소리와 번갈아 난다.","서고",alignment=AL(j=60),fame=15,stats={"mind":4},flags=["장원_식구","장원_장서"])
H(J,"시인과검","술 한 동이를 사고, 그 시를 장원 서고에 다 적어 두게 한다","시객은 서고 마루에서 열흘을 취해 있었다. 깨어 있는 틈에 적은 시가 책 한 권이 되었다. 붓끝이 지나간 자리마다 초식의 길이 보인다. 책은 궤 맨 아래에 넣었다. 값을 매길 수 있는 책이다.","서고",alignment=AL(s=40),silver=-15,stats={"martial":4,"mind":3},flags=["장원_장서"])
H(J,"서생호위","여덟 번째 과거 대신 장원 서고의 서리 자리를 내민다","서생은 나귀 고삐를 쥐고 오래 서 있었다. \"일곱 번 떨어진 글이라도 쓸 데가 있습니까.\" 서고의 책이 처음으로 제자리를 찾았다. 그는 여전히 밤마다 과거 글을 짓는다. 붙을 생각은 이제 없다고 한다.","서고",alignment=AL(s=40),stats={"mind":5},flags=["장원_장서"])
H(J,"빈집의유골","묻어 주고, 책은 그의 이름을 적어 장원 서고에 올린다","유골을 볕 드는 언덕에 묻었다. 책 첫 장에 새겨진 글과 묻은 자리를 적어 넣었다. 서고의 시렁에 이름 있는 책이 한 권 늘었다. 원한은 따라오지 않았다.","서고",alignment=AL(j=50),stats={"mind":5},art_mastery={"심공":5},flags=["장원_장서"])
H(J,"대협의장례","조문객 명단을 장원 서고에 베껴 두게 한다. 독을 쓴 자는 그 안에 있다","서고의 붓이 사흘 만에 명단을 다 옮겼다. 누가 누구 곁에 앉았고 누가 먼저 일어났는지까지. 독을 쓴 자의 이름은 아직 모른다. 다만 이 명단을 쥔 집을 함부로 대할 자는 이제 없다.","서고",alignment=AL(m=60),stats={"mind":5},fame=10,flags=["장원_장서"])
H(A,"수련_피란민","피란민 가운데 쓸 만한 장정만 골라 장원으로 보낸다","수레는 진창에 그대로 있었다. 장정 여섯이 문패의 탁본을 받아 들고 식구를 뒤에 남긴 채 산자락으로 떠났다. 장원의 담은 그들이 쌓을 것이다. 남은 식구들이 나를 오래 보았다.","객사",alignment=AL(m=60),stats={"external":3},flags=["장원_식객"])
# 결전을 앞둔 본편
H(S,"전야_맹세","산자락의 대문과 그 안의 얼굴들을 떠올린다","대문은 주인이 있는 동안만 열린다고 청지기가 말했었다. 돌아가지 못하면 그 문이 닫힌다. 솥 둘레에 앉던 얼굴들이 하나씩 떠올랐다. 손이 떨리지 않았다.",True,req={"flag":"장원_식구"},stats={"mind":8,"internal":4})
H(S,"산아래_밤","산 아래까지 따라온 장원 사람들과 저녁을 먹는다","청지기가 솥을 지고 와 있었다. 식객 몇과 약방 사람도 있었다. 산에는 못 오른다. 대신 내려오는 길목마다 불을 피워 두겠다고 한다. 국은 짰고 밥은 질었다. 남기지 않았다.",{"size":4},stats={"mind":6},hp_pct=40,qi_pct=40)
H(J,"먼저오른자들","이름을 아는 자는 적어 장원 서고에 올리고, 모두 묻는다","품에서 나온 패와 병기의 이름을 하나씩 적었다. 모르는 자는 생김새를 적었다. 장원 서고에 이 고개의 이름으로 책 한 권이 생길 것이다. 찾으러 오는 식구가 있으면 청지기가 펴 보일 것이다.","서고",alignment=AL(j=60),fame=20,stats={"mind":6},flags=["장원_장서"])
H(J,"결전전우","이름을 묻고, 장원 객사에 그의 방을 내준다","늙은 협객은 지도를 내 손에 쥐여 주고도 한참 손을 놓지 않았다. \"스무 해 만에 지붕 밑에서 자 보겠군.\" 문패의 탁본을 받아 든 그가 지팡이를 짚고 산자락 쪽으로 떠났다. 내려오면 그 방에서 산 이야기를 듣기로 했다.","객사",stats={"mind":4,"martial":3},flags=["장원_식객"])
