manor("장원_밤손님",[3,4],{"객사":2},"한 지붕 아래의 두 손님",
 "객사에 손님 둘이 들었다. 하나는 비단 장수라는데 손바닥에 굳은살이 병기 쥐는 자리에만 박였다. 다른 하나는 그 비단 장수가 밥을 먹을 때마다 문 쪽 자리에 앉는 늙은 상인이다. 청지기가 귓속말을 한다. \"비단 장수는 살막의 사람입니다. 늙은 상인이 표적이고요. 이 집에서 일이 나면 객사에 손님이 끊깁니다.\"",
 [C("내 집에서는 피를 보지 못한다고 살수에게 이른다",O("살수는 찻잔을 내려놓고 고개를 숙였다. \"집주인의 법은 따릅니다. 대문 밖은 내 법이고.\" 늙은 상인에게는 뒷문과 말 한 필을 내주었다. 살수는 이튿날 숙박료를 곱으로 넣고 떠났다.",alignment=AL(j=60),fame=15,stats={"mind":5},flags=["장원_식구"])),
  C("상인에게 살수의 값보다 더 받고 길을 터 준다",O("늙은 상인은 전대를 통째로 내놓았다. 식객 둘이 그를 밤길로 데리고 나갔다. 살수는 빈방을 보고 웃었다. \"이 집은 값을 아는 집이군. 다음에는 내가 먼저 흥정하겠소.\"",alignment=AL(s=70),silver=160)),
  C("살수와 겨뤄 내 집의 법을 가르친다",O("살수가 마당에 무릎을 꿇었다. 비단 보따리에서 나온 것은 비단이 아니었다. 살막은 그 뒤로 이 집 손님의 이름을 장부에 적지 않는다고 한다.",battle="살막살수",foe="비단 장수 차림의 살수 은침 여소",foe_line="\"집주인이 손님의 일에 끼는 집은 오래 못 가오.\"",alignment=AL(m=40),stats={"martial":6,"external":3},fame=20))])
manor("장원_떠돌이검객",[2,3],"연무장","현판 없는 마당의 도전자",
 "연무장에 낯선 무인이 병기를 짚고 서 있다. 고을 무관을 차례로 돌며 현판을 떼어 온 자라고 한다. 등짐에 현판 조각이 여럿 꽂혔다. \"이 집에는 뗄 현판도 없군. 그럼 주인의 한 수라도 가져가야겠소.\" 아이들이 담 밑에 줄지어 서서 나를 본다.",
 [C("아이들이 보는 앞에서 한 수를 받는다",O("그의 병기가 마당 흙에 꽂혔다. 그는 등짐의 현판 조각을 내려놓고 갔다. 돌려줄 곳이 여럿이다. 아이들은 그날 밤늦도록 연무장을 떠나지 않았다.",battle="떠돌이패",spar=True,foe="현판을 떼러 다니는 무인 독목 구상",foe_line="\"주인이 지면 이 마당의 흙을 한 줌 가져가겠소.\"",fame=20,stats={"martial":6},battles=1,flags=["장원_제자"])),
  C("식객 가운데 하나를 내보내고 판돈을 건다",O("식객이 이겼다. 고을 사람들이 건 판돈의 절반이 장원 궤로 들어왔다. 도전자는 떼어 온 현판을 팔아 밥값을 치르고 갔다.",alignment=AL(s=60),silver=110,flags=["장원_식객"])),
  C("등짐의 현판을 모두 빼앗아 장원 담에 건다",O("그는 빈 등짐으로 산을 내려갔다. 담에 걸린 현판을 보고 고을 무관들이 차례로 찾아와 머리를 숙였다. 돌려주지는 않았다.",battle="떠돌이패",foe="현판을 떼러 다니는 무인 독목 구상",foe_line="\"남이 뗀 것을 다시 떼겠다는 거요? 도둑의 도둑이군.\"",alignment=AL(m=70),fame=15,stats={"external":5,"martial":3}))])
manor("장원_독초",[3,4],{"약방":2},"약초밭의 낯선 풀",
 "약방 사람이 새벽에 문을 두드린다. 약초밭 한 고랑에 심은 적 없는 풀이 올라왔다. 잎은 당귀를 닮았는데 뿌리를 달이면 사람이 사흘 만에 죽는다. 누가 밤에 담을 넘어 심고 간 것이다. 그 고랑의 약은 내일 고을로 내려갈 참이었다.",
 [C("고랑을 통째로 태우고 고을에 사실대로 알린다",O("연기가 한나절 올랐다. 고을 사람들은 놀랐지만 약방 앞의 줄은 줄지 않았다. 숨기지 않는 집의 약이라는 것이다. 풀을 심은 자는 이웃 고을 약재상이 보낸 자였다.",alignment=AL(j=70),fame=20,stats={"mind":5},flags=["장원_마을"])),
  C("심은 자를 잡아 누가 보냈는지 값을 매긴다",O("밤에 고랑 옆에 숨어 있다가 담을 넘는 자를 잡았다. 이웃 고을 약재상의 머슴이었다. 약재상은 입막음 값으로 가게의 절반을 내놓았다.",alignment=AL(s=70),silver=180,stats={"mind":3})),
  C("그 풀을 뽑지 않고 따로 길러 둔다",O("고랑에 울타리를 치고 팻말을 꽂지 않았다. 약방 사람은 말없이 그 고랑에도 물을 준다. 독도 약재다. 쓸 곳이 생길 것이다.",alignment=AL(m=70),stats={"internal":5,"mind":2},item="마비독물"))])
manor("장원_금서",[3,4],{"서고":2},"관아가 찾는 책",
 "관아의 서리가 포졸을 데리고 와 서고를 뒤지겠다고 한다. 조정이 금한 책이 이 집에 들어왔다는 것이다. 책은 정말 있다. 지난달 떠돌이 서생이 맡기고 간 궤 안에, 쫓겨난 사관이 적은 실록의 초고가 들어 있다. 서리가 말한다. \"내놓으면 집은 건드리지 않겠소. 숨기면 서고째 봉하오.\"",
 [C("그런 책은 없다고 하고 서고 문을 막아선다",O("서리는 내 얼굴과 병기를 번갈아 보다가 물러갔다. 초고는 궤 밑바닥에 그대로 있다. 맡긴 서생은 끝내 찾으러 오지 않았다. 책은 읽는 사람이 있는 한 남는다.",alignment=AL(j=70),fame=15,stats={"mind":6},flags=["장원_장서"])),
  C("베낀 것을 내주고 초고는 따로 둔다",O("밤새 필사한 것을 궤에 넣어 내주었다. 서리는 책을 받아 불에 던지고 흡족해서 돌아갔다. 초고의 값은 그 불길을 본 뒤로 곱절이 되었다.",alignment=AL(s=70),silver=90,stats={"mind":4},flags=["장원_장서"])),
  C("책을 내주고 서리에게 빚을 지운다",O("서리는 공을 세웠다. 그 공이 누구 덕인지 그는 안다. 이 고을 관아의 문서 가운데 장원이 보지 못할 것은 이제 없다.",alignment=AL(m=60),stats={"mind":5},fame=10))])
manor("장원_혼례",[3,4,5],"객사","마당의 초례청",
 "청지기가 어려운 얼굴로 묻는다. 객사에 든 식구 가운데 둘이 혼례를 올리겠다고 한다. 갈 곳 없이 들어온 사람들이라 내줄 것도 받을 것도 없다. 초례청을 마당에 차려도 되겠느냐는 것이다. 주례는 주인이 서야 한다고 다들 우긴다.",
 [C("마당을 내주고 주례를 선다",O("술은 묽었고 닭은 한 마리였다. 그래도 마당이 꽉 찼다. 신부가 절을 하다 울었고 청지기가 따라 울었다. 대문은 그날 밤새 열려 있었다.",stats={"mind":8},hp_pct=20)),
  C("혼례는 치르되 잔칫상 값은 삯에서 떼기로 한다",O("청지기가 장부에 줄을 그었다. 신랑은 세 해 치 삯을 미리 당겨 썼다. 그래도 웃었다. 갚을 것이 있다는 것은 머물 곳이 있다는 뜻이라고 한다.",alignment=AL(s=50),silver=40,stats={"mind":4})),
  C("내 집에서 식구가 불어나는 것은 내가 정한다고 이른다",O("둘은 말없이 고개를 숙였다. 혼례는 대문 밖 서낭당에서 치렀다. 돌아와서는 전과 같이 일했다. 다만 나를 보면 먼저 길을 비킨다.",alignment=AL(m=60),stats={"external":3,"mind":2}))])
MANOR["장원_혼례"]["requires"]["flag"]="장원_식구"
manor("장원_산을보는마당",[5],{"size":5},"산으로 가는 주인",
 "천마봉의 초대장 이야기가 산자락의 장원까지 올라왔다. 식객들이 마루에 모여 있다. 주인이 그 산에 오른다는 것을 다들 안다. 맨 앞의 식객이 말한다. \"산 위는 우리가 낄 자리가 아닙니다. 그래도 산 아래까지는 가겠습니다. 내려오는 길을 누가 지켜야 하지 않겠습니까.\"",
 [C("내려오는 길목을 맡긴다",O("식객들이 병기를 챙겼다. 약방 사람은 약 궤를 쌌다. 청지기는 솥을 닦았다. 산 아래 길목마다 장원의 불이 켜질 것이다. 오를 때 등 뒤가 어둡지 않다.",alignment=AL(j=50),stats={"mind":8,"internal":3},flags=["장원_길목"])),
  C("산 아래 장터에서 오르는 무인들을 상대로 객사를 열게 한다",O("청지기의 눈이 빛났다. 오르는 자는 많고 묵을 곳은 적다. 산 아래에 장원의 깃발을 단 천막이 섰다. 내려오는 자가 적다는 것만 장부에 맞지 않는다.",alignment=AL(s=60),silver=150,flags=["장원_길목"])),
  C("아무도 따라오지 말라 한다. 집을 지키라고",O("식객들은 흩어졌다. 맨 앞의 식객만 마루에 남아 산을 보았다. \"주인이 없는 동안 문은 닫아 두겠습니다. 다시 여는 것은 주인의 손으로 하십시오.\"",alignment=AL(m=40),stats={"external":5,"martial":4}))])
manor("장원_넘치는궤",[2,3,4],"객사","넘치는 숙박료 궤",
 "청지기가 궤를 끌고 온다. 숙박료가 궤에 다 들어가지 않는다. 고을 사람들이 찾아와 그 은자를 꾸어 달라고 한다. 흉년에 씨앗 살 돈이 없다는 것이다. 청지기가 속삭인다. \"이자를 붙이면 내년에는 궤가 둘입니다. 못 갚으면 밭이 우리 것이고요.\"",
 [C("이자 없이 꾸어 주고 햇곡으로 받는다",O("청지기는 한숨을 쉬며 장부에 적었다. 가을에 고을 사람들은 꾼 것보다 많은 곡식을 지고 왔다. 궤는 불지 않았지만 광이 찼다.",alignment=AL(j=60),fame=15,silver=-40,stats={"mind":5},flags=["장원_마을"])),
  C("고을의 관례대로 이자를 붙인다",O("가을에 궤가 둘이 되었다. 못 갚은 집이 셋 있었다. 청지기가 그 집들의 밭문서를 들고 와 어찌할지 묻는다. 일단 궤에 넣어 두라 했다.",alignment=AL(s=60),silver=140)),
  C("꾸어 주지 않는다. 궤를 하나 더 짠다",O("고을 사람들은 빈손으로 내려갔다. 이듬해 봄 그 가운데 몇 집이 고을을 떴다. 빈 밭은 헐값에 나왔고 장원이 샀다.",alignment=AL(m=60),silver=60,stats={"external":2}))])
MANOR["장원_넘치는궤"]["requires"]["flag"]="장원_셈"
manor("장원_담을넘은아이",[2,3,4],"객사","가시나무 담을 넘은 아이",
 "닫아 둔 대문 안, 광 뒤에서 아이 하나가 잡혔다. 가시나무에 팔이 다 긁혔다. 훔친 것은 찬밥 한 덩이다. 청지기가 아이의 뒷덜미를 쥐고 묻는다. \"부르지 않은 자는 들이지 않는 집입니다. 어찌할까요.\" 아이는 울지 않고 나를 똑바로 본다.",
 [C("밥을 마저 먹이고 대문으로 내보낸다. 다음에는 문을 두드리라고",O("아이는 밥을 다 먹고 대문으로 걸어 나갔다. 사흘 뒤 대문 두드리는 소리가 났다. 청지기가 나를 보았다. 열어 주라 했다. 닫힌 집에도 두드릴 문은 있어야 한다.",alignment=AL(j=60),stats={"mind":6},flags=["장원_식구"])),
  C("담을 넘은 솜씨를 사서 심부름꾼으로 쓴다",O("가시나무 담을 맨손으로 넘은 아이다. 삯을 정하고 고을의 소식을 물어 오게 했다. 아이는 밥값보다 훨씬 많은 것을 물어 온다.",alignment=AL(s=50),stats={"mind":4},silver=30,flags=["장원_식구"])),
  C("담 밖에 세워 두어 넘으려는 자들이 보게 한다",O("아이는 해 질 녘까지 대문 밖에 서 있었다. 그 뒤로 담을 넘는 자가 없다. 아이는 밤에 사라졌다. 광의 찬밥 그릇이 하나 비어 있었다.",alignment=AL(m=70),stats={"external":4}))])
MANOR["장원_담을넘은아이"]["requires"]["flag"]="장원_닫힌"
